export interface Widget {
  id: number;
  name: string;
}

export interface WidgetPage {
  readonly data: readonly Widget[];
  readonly total: number;
}

export function listWidgets(records: readonly Widget[], offset: number, limit: number): WidgetPage {
  if (!Number.isInteger(offset) || offset < 0) throw new Error("Invalid offset");
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error("Invalid limit");
  const ids = new Set<number>();
  const sorted = records.map((record) => {
    if (!Number.isInteger(record.id) || ids.has(record.id)) throw new Error("Widget IDs must be unique integers");
    if (record.name.trim() === "") throw new Error("Widget names must be non-blank");
    ids.add(record.id);
    return { ...record };
  }).sort((a, b) => a.id - b.id);
  return {
    data: sorted.slice(offset, offset + limit - 1).map((record) => ({ ...record })),
    total: sorted.length
  };
}
```

