import { listWidgets } from './solution';
import type { Widget, WidgetPage } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(action: () => unknown, message: string): void {
  let failed = false;
  try { action(); } catch (error) { failed = error instanceof Error; }
  if (!failed) throw new Error(message);
}

for (const offset of [-1, 0.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  throws(() => listWidgets([], offset, 1), 'invalid offset');
}
for (const limit of [0, -1, 1.5, 101, Number.NaN, Number.POSITIVE_INFINITY]) {
  throws(() => listWidgets([], 0, limit), 'invalid limit');
}

throws(() => listWidgets([{ id: 1.5, name: 'x' }], 0, 1), 'noninteger ID');
throws(() => listWidgets([{ id: 1, name: 'x' }, { id: 1, name: 'y' }], 0, 2), 'duplicate ID');
throws(() => listWidgets([{ id: 1, name: '' }], 0, 1), 'empty name');
throws(() => listWidgets([{ id: 1, name: '   ' }], 0, 1), 'blank name');

const empty = listWidgets([], 0, 100);
equal(empty.total, 0, 'empty total');
equal(empty.data.length, 0, 'empty data');

const records: Widget[] = [
  { id: 30, name: 'thirty' },
  { id: -2, name: 'negative' },
  { id: 10, name: 'ten' },
  { id: 20, name: 'twenty' }
];
const originalOrder = records.map((record) => record.id);
const page = listWidgets(records, 1, 2);
equal(page.total, 4, 'total before pagination');
equal(page.data.length, 2, 'returns exact limit when available');
equal(page.data[0].id, 10, 'sorted and offset first');
equal(page.data[1].id, 20, 'slice includes second item');
for (let i = 0; i < records.length; i += 1) equal(records[i].id, originalOrder[i], 'input order unchanged');

records[2].name = 'changed input';
equal(page.data[0].name, 'ten', 'result does not retain input object');
(page.data[0] as { name: string }).name = 'changed output';
const fresh = listWidgets(records, 1, 2);
equal(fresh.data[0].name, 'changed input', 'returned objects are newly allocated');

const finalItem = listWidgets(records, 3, 100);
equal(finalItem.data.length, 1, 'up to limit at end');
equal(finalItem.data[0].id, 30, 'last item');
const beyond: WidgetPage = listWidgets(records, 4, 1);
equal(beyond.total, 4, 'beyond offset preserves total');
equal(beyond.data.length, 0, 'offset at end empty');

